import Link from 'next/link';import type {Project} from '@/data/site';
export default function ProjectCard({project}: {project:Project;index?:number}){const content=<><div className="project-image"><img src={project.image} alt={`${project.title} project preview`} loading="lazy"/><span className="project-arrow">↗</span></div><div className="project-meta"><div><h3>{project.title}</h3><p>{project.category}</p></div></div></>;return project.external?<a className="project-card" href={project.external} target="_blank" rel="noreferrer">{content}</a>:<Link className="project-card" href={`/projects/${project.slug}`}>{content}</Link>}
